import{_ as a,c as t,o as s,b0 as i}from"./chunks/framework.Becqh7-x.js";const r="/linux-dev-docs/assets/image-20230910104505665.BxFHUUER.png",n="/linux-dev-docs/assets/image-20230910105025878.zoNXhDNL.png",p="/linux-dev-docs/assets/image-20240121142504171.i476e94i.png",o="/linux-dev-docs/assets/image-20230910103319234.BBebS9DA.png",l="/linux-dev-docs/assets/image-20240121143900941.DMZp5WKH.png",c="/linux-dev-docs/assets/image-20230910105439401.D86iYL85.png",C="/linux-dev-docs/assets/image-20260115172342430.yyPNj33r.png",d="/linux-dev-docs/assets/image-20230910110046239._WaJlaOs.png",I="/linux-dev-docs/assets/image-20260115172526398.DCoCkNR4.png",h="/linux-dev-docs/assets/image-20260115172730975.DkCtayjK.png",u="/linux-dev-docs/assets/image-20260115183816999.Urw2w2Md.png",m="/linux-dev-docs/assets/image-20260115184055687.ComVyGT6.png",g="/linux-dev-docs/assets/image-20260115184135205.6SNCFl5k.png",R="/linux-dev-docs/assets/image-20260115184242910.GtfXoSAA.png",b="/linux-dev-docs/assets/image-20260115184325917.DWZlCjLD.png",A="/linux-dev-docs/assets/image-20260115184500316.CFqZgzr4.png",P="/linux-dev-docs/assets/image-20260115184609692.U-83CwBD.png",D="/linux-dev-docs/assets/image-20260115184740518.BSOgS_Ch.png",M="data:image/png;base64,",q="/linux-dev-docs/assets/image-20230910111946129.DHl76q10.png",v="/linux-dev-docs/assets/image-20230910112124153.DVUIoWy7.png",U="/linux-dev-docs/assets/image-20230910112207791.BEC86Csn.png",G="/linux-dev-docs/assets/image-20230910112331142.D-C2xuep.png",E=JSON.parse('{"title":"LV020-CortexA7的中断系统","description":null,"frontmatter":{"title":"LV020-CortexA7的中断系统","date":"2026-01-15T16:02:08.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/bare/interrupt/126d2cf79c9033f52cdd6059","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-15T16:02:08.831Z","fulluuid":"52cdd60590fb41c7b50bc4194609f5ee","useduuid":"52cdd6059"}},"headers":[],"relativePath":"sdoc/bare/interrupt/126d2cf79c9033f52cdd6059.md","filePath":"sdoc/25-裸机开发/35-中断与异常/LV020-CortexA7的中断系统.md","lastUpdated":1768604092000}'),x={name:"sdoc/bare/interrupt/126d2cf79c9033f52cdd6059.md"};function k(Q,e,_,f,S,V){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="lv020-cortexa7的中断系统" tabindex="-1">LV020-CortexA7的中断系统 <a class="header-anchor" href="#lv020-cortexa7的中断系统" aria-label="Permalink to &quot;LV020-CortexA7的中断系统&quot;">​</a></h1><h2 id="一、cortex-a7-中断系统简介" tabindex="-1">一、Cortex-A7 中断系统简介 <a class="header-anchor" href="#一、cortex-a7-中断系统简介" aria-label="Permalink to &quot;一、Cortex-A7 中断系统简介&quot;">​</a></h2><h3 id="_1-8个中断" tabindex="-1">1. 8个中断？ <a class="header-anchor" href="#_1-8个中断" aria-label="Permalink to &quot;1. 8个中断？&quot;">​</a></h3><p>Cortex-A7 也有中断向量表，中断向量表也是在代码的最前面。 CortexA7 内核有 8 个异常中断，这 8 个异常中断的中断向量表如表 ：</p><img src="'+r+'" alt="image-20230910104505665" style="zoom:50%;"><p>中断向量表里面都是中断服务函数的入口地址，因此一款芯片有什么中断都是可以从中断向量表看出来的。从表中可以看出， Cortex-A7 一共有 8 个中断，而且还有一个中断向量未使用，实际只有 7 个中断。</p><p>①、复位中断(Rest)， CPU 复位以后就会进入复位中断，我们可以在复位中断服务函数里面做一些初始化工作，比如初始化 SP 指针、 DDR 等等。</p><p>②、未定义指令中断(Undefined Instruction)，如果指令不能识别的话就会产生此中断。</p><p>③、软中断(Software Interrupt,SWI)，由 SWI 指令引起的中断， Linux 的系统调用会用 SWI指令来引起软中断，通过软中断来陷入到内核空间。</p><p>④、指令预取中止中断(Prefetch Abort)，预取指令的出错的时候会产生此中断。</p><p>⑤、数据访问中止中断(Data Abort)，访问数据出错的时候会产生此中断。</p><p>⑥、 IRQ 中断(IRQ Interrupt)，外部中断，前面已经说了，芯片内部的外设中断都会引起此中断的发生。</p><p>⑦、 FIQ 中断(FIQ Interrupt)，快速中断，如果需要快速处理中断的话就可以使用此中断。</p><p>难道一个能跑 Linux 的芯片只有这 7 个中断？明显不可能的！那类似 STM32 中的EXTI9_5_IRQHandler、 TIM2_IRQHandler 这样的中断向量在哪里？ I2C、SPI、定时器等等的中断怎么处理呢？这个就是 Cortex-A 和 Cotex-M 在中断向量表这一块的区别，对于 Cortex-M 内核来说，中断向量表列举出了一款芯片所有的中断向量，包括芯片外设的所有中断。对于 CotexA 内核来说并没有这么做，在上面的表中有个 IRQ 中断， Cortex-A 内核 CPU 的所有外部中断都属于这个 IRQ 中断，当任意一个外部中断发生的时候都会触发 IRQ 中断。在 IRQ 中断服务函数里面就可以读取指定的寄存器来判断发生的具体是什么中断，进而根据具体的中断做出相应的处理。这些外部中断和 IRQ 中断的关系如下：</p><img src="'+n+'" alt="image-20230910105025878" style="zoom:50%;"><p>左侧的 Software0_IRQn~PMU_IRQ2_IRQ 这些都是 I.MX6U 的中断，他们都属于 IRQ 中断。当图中左侧这些中断中任意一个发生的时候 IRQ 中断都会被触发，所以我们需要在 IRQ 中断服务函数中判断究竟是左侧的哪个中断发生了，然后再做出具体的处理。</p><h3 id="_2-gic-控制器简介" tabindex="-1">2. GIC 控制器简介 <a class="header-anchor" href="#_2-gic-控制器简介" aria-label="Permalink to &quot;2. GIC 控制器简介&quot;">​</a></h3><h4 id="_2-1-gic-控制器总览" tabindex="-1">2.1 GIC 控制器总览 <a class="header-anchor" href="#_2-1-gic-控制器总览" aria-label="Permalink to &quot;2.1 GIC 控制器总览&quot;">​</a></h4><p>GIC 是 ARM 公司给 Cortex-A/R 内核提供的一个中断控制器，类似 Cortex-M 内核中的NVIC。目前 GIC 有 4 个版本:V1~V4， V1 是最老的版本，已经被废弃了。 V2~V4 目前正在大量的使用。 GIC V2 是给 ARMv7-A 架构使用的，比如 Cortex-A7、 Cortex-A9、 Cortex-A15 等，V3 和 V4 是给 ARMv8-A/R 架构使用的，也就是 64 位芯片使用的。</p><p>I.MX6U 是 Cortex-A 内核的，因此我们主要学习 GIC V2。 GIC V2 最多支持 8 个核。 ARM 会根据 GIC 版本的不同研发出不同的 IP 核，那些半导体厂商直接购买对应的 IP 核即可，比如 ARM 针对 GIC V2 就开发出了 GIC400 这个中断控制器 IP 核。</p><p>我们来简单了解一下GIC V2，我们打开《ARM® Generic Interrupt Controller Architecture version 2.0》这篇文档，找到3.9 Example GIC usage models 一节，这一节有下面这么一个图：</p><img src="'+p+'" alt="image-20240121142504171" style="zoom:50%;"><p>如上图所示，硬件中断信号发送到 GIC（ Generic Interrupt Controller），GIC 产生一个 FIQ 或 IRQ 信号给 CPU。 GPIO 模块、 UART 模块均能产生硬件中断。在初始化中断时，要初始化这 4 部分：产生中断的源头(GPIO 模块或 UART模块等)、 GIC(内部有 Distributor 或 CPU interface)、 CPU 本身(设置 CPSR寄存器)，如下图</p><img src="'+o+'" alt="image-20240121143724299" style="zoom:50%;"><p>GIC 的主要作用可以归结为接受硬件中断信号，并进行简单的处理，按照一定的设置策略，分给对应的 CPU 处理，我们再找到3.9.3 Supporting IRQs and FIQs in a virtualized processor environment 一节，有这么一个图：</p><img src="'+l+'" alt="image-20240121143900941" style="zoom:67%;"><p>当 GIC 接收到外部中断信号以后就会报给 ARM 内核，但是ARM 内核只提供了四个信号给 GIC 来汇报中断情况： VFIQ（虚拟快速 FIQ）、VIRQ（虚拟外部 IRQ）、FIQ（快速中断 IRQ）、IRQ（外部中断 IRQ），他们之间的关系如图：</p><img src="'+c+'" alt="image-20230910105439401" style="zoom:50%;"><p>VFIQ 和 VIRQ 是针对虚拟化，剩下就是 IRQ 和 FIQ。GPIO 中断属于 IRQ 中断，所以在后面的GPIO中断实验中 GIC 上报 IRQ 信号给 ARM 内核。 这里我们先不关心虚拟化，剩下的就是 FIQ 和 IRQ 了，那么 GIC 是如何完成这个工作的呢？ GICV2 的逻辑图如图（<a href="https://developer.arm.com/documentation/ihi0048/latest" target="_blank" rel="noreferrer">ARM Generic Interrupt Controller Architecture Specification - Version 2.0 (B.b)</a>） ：</p><p><img src="'+C+'" alt="image-20260115172342430"></p><p>左侧部分就是中断源，中间部分就是 GIC 控制器，最右侧就是中断控制器向处理器内核发送中断信息。GIC 控制器包括分发器（ Distributor）和 CPU 接口端（ CPU interface）。 分发器（ Distributor）主要完成对整个中断控制器使能，设置中断优先级，设置中断触发方式，决定每个中断信号发送到哪一个具体的 CPU 上执行。CPU 接口端（ CPU interface）主要完成使能和发送一个具体的中断信号到特定的 CPU 上，确认中断已被 CPU 接受、处理以及处理完成，设置 CPU 能接受中断的优先级以及基于级别的中断抢占。</p><p>所以中断信号先到达分发器，分发器根据该中断所设定的 CPU，把中断发送到 CPU对应的 CPU interface 上；在 CPU interface 里判断该中断的优先级是否足够高，能否抢断或打断当前的中端处理，如果可以， CPU interface 就会发送一个物理的 signa 到 CPU 的 IRQ 线上； CPU 接收到中断信号，转到中断处理模式进行处理。</p><p>然后我们重点要看的肯定是中间的 GIC 部分， GIC 将众多的中断源分为分为三类：</p><p>①、<strong>SPI(Shared Peripheral Interrupt)</strong>，共享中断，顾名思义，所有 Core 共享的中断，这个是最常见的，那些<strong>外部中断都属于 SPI 中断</strong>(注意！不是 SPI 总线那个中断) 。比如按键中断、串口中断等等，这些中断所有的 Core 都可以处理，不限定特定 Core。</p><p>②、<strong>PPI(Private Peripheral Interrupt)</strong>，私有中断，我们说了 GIC 是支持多核的，每个核肯定有自己独有的中断。这些独有的中断肯定是要指定的核心处理，因此这些中断就叫做私有中断。</p><p>③、<strong>SGI(Software-generated Interrupt)</strong>，软件中断，由软件触发引起的中断，通过向寄存器GICD_SGIR 写入数据来触发，系统会使用 SGI 中断来完成多核之间的通信。</p><h4 id="_2-2-中断-id" tabindex="-1">2.2 中断 ID <a class="header-anchor" href="#_2-2-中断-id" aria-label="Permalink to &quot;2.2 中断 ID&quot;">​</a></h4><p>中断源有很多，为了区分这些不同的中断源肯定要给他们分配一个唯一 ID，这些 ID 就是中断 ID。每一个 CPU 最多支持 1020 个中断 ID，中断 ID 号为 ID0~ID1019。这 1020 个 ID 包含了 PPI、 SPI 和 SGI，那么这三类中断是如何分配这 1020 个中断 ID 的呢？这 1020 个 ID 分配如下：</p><ul><li><p>ID0~ID15：这 16 个 ID 分配给 SGI。</p></li><li><p>ID16~ID31：这 16 个 ID 分配给 PPI。</p></li><li><p>ID32~ID1019：这 988 个 ID 分配给 SPI，像 GPIO 中断、串口中断等这些外部中断 ，至于具体到某个 ID 对应哪个中断那就由半导体厂商根据实际情况去定义了。</p></li></ul><p>比如 I.MX6U 的总共使用了 128 个中断 ID，加上前面属于 PPI 和 SGI 的 32 个 ID， I.MX6U 的中断源共有 128+32=160个，这 128 个中断 ID 对应的中断在《I.MX6ULL 参考手册》的“3.2 Cortex A7 interrupts”小节，中断源如表:</p><img src="'+d+'" alt="image-20230910110046239" style="zoom:50%;"><p>这里就不全部列出了，我们前面移植了 NXP 官方 SDK中的文件 MCIMX6Y2C.h，在此文件中定义了一个枚举类型 IRQn_Type，此枚举类型就枚举出了 I.MX6U 的所有中断，</p><h4 id="_2-3-gic-逻辑分块" tabindex="-1">2.3 GIC 逻辑分块 <a class="header-anchor" href="#_2-3-gic-逻辑分块" aria-label="Permalink to &quot;2.3 GIC 逻辑分块&quot;">​</a></h4><p>GIC 架构分为了两个逻辑块： Distributor 和 CPU Interface，也就是分发器端和 CPU 接口端。</p><ul><li><strong>Distributor(分发器端)</strong></li></ul><p>此逻辑块负责处理各个中断事件的分发问题，也就是中断事件应该发送到哪个 CPU Interface 上去。分发器收集所有的中断源，可以控制每个中断的优先级，它总是将优先级最高的中断事件发送到 CPU 接口端。分发器端要做的主要工作如下：</p><p>①、全局中断使能控制。</p><p>②、控制每一个中断的使能或者关闭。</p><p>③、设置每个中断的优先级。</p><p>④、设置每个中断的目标处理器列表。</p><p>⑤、设置每个外部中断的触发模式：电平触发或边沿触发。</p><p>⑥、设置每个中断属于组 0 还是组 1。</p><ul><li><strong>CPU Interface(CPU 接口端)</strong></li></ul><p>CPU 接口端听名字就知道是和 CPU Core 相连接的，因此在每个 CPU Core 都可以在 GIC 中找到一个与之对应的 CPU Interface。 CPU 接口端就是分发器和 CPU Core 之间的桥梁， CPU 接口端主要工作如下：</p><p>①、使能或者关闭发送到 CPU Core 的中断请求信号。</p><p>②、应答中断。</p><p>③、通知中断处理完成。</p><p>④、设置优先级掩码，通过掩码来设置哪些中断不需要上报给 CPU Core。</p><p>⑤、定义抢占策略。</p><p>⑥、当多个中断到来的时候，选择优先级最高的中断通知给 CPU Core。</p><h4 id="_2-4-imx6ull-gic中断寄存器" tabindex="-1">2.4 IMX6ULL GIC中断寄存器 <a class="header-anchor" href="#_2-4-imx6ull-gic中断寄存器" aria-label="Permalink to &quot;2.4 IMX6ULL GIC中断寄存器&quot;">​</a></h4><p>GIC 寄存器分为 Distributor register 和 CPU interface register。寄存器数目较多，这里我们看一下后面做IMX6ULL外部中断实验的时候需要我们设置的寄存器。</p><h5 id="_4-1-gicc-iar-寄存器" tabindex="-1">4.1 GICC_IAR 寄存器 <a class="header-anchor" href="#_4-1-gicc-iar-寄存器" aria-label="Permalink to &quot;4.1 GICC_IAR 寄存器&quot;">​</a></h5><p>《ARM® Generic Interrupt Controller Architecture version 2.0》的4.4.4 Interrupt Acknowledge Register, GICC_IAR 一节是介绍这个寄存器的：</p><p><img src="'+I+'" alt="image-20260115172526398"></p><table tabindex="0"><thead><tr><th>位域</th><th>名称</th><th>读写权限</th><th>描述</th></tr></thead><tbody><tr><td>bit[31:13]</td><td>-</td><td></td><td>保留</td></tr><tr><td>bit[12:10]</td><td>CPUID</td><td>R</td><td>对于SGI 类中断，它表示谁发出了中断。例如，值为3表示该请求是通过对CPU-interface3上的GICD_SGIR的写操作生成的。</td></tr><tr><td>bit[9:0]</td><td>Interrupt ID</td><td>R</td><td>中断ID</td></tr></tbody></table><h5 id="_4-2-gicc-eoir-寄存器" tabindex="-1">4.2 GICC_EOIR 寄存器 <a class="header-anchor" href="#_4-2-gicc-eoir-寄存器" aria-label="Permalink to &quot;4.2 GICC_EOIR 寄存器&quot;">​</a></h5><p>《ARM® Generic Interrupt Controller Architecture version 2.0》的4.4.5 End of Interrupt Register, GICC_EOIR 一节：</p><p><img src="'+h+`" alt="image-20260115172730975"></p><p>写此寄存器，表示某中断已经处理完毕。 GICC_IAR 的值表示当前在处理的中断，把 GICC_IAR 的值写入 GICC_EOIR 就表示中断处理完了。</p><h2 id="二、cp15-协处理器" tabindex="-1">二、CP15 协处理器 <a class="header-anchor" href="#二、cp15-协处理器" aria-label="Permalink to &quot;二、CP15 协处理器&quot;">​</a></h2><h3 id="_1-相关指令" tabindex="-1">1. 相关指令 <a class="header-anchor" href="#_1-相关指令" aria-label="Permalink to &quot;1. 相关指令&quot;">​</a></h3><p>关 于 CP15 协处理 器和其 相关寄存器的详细内容请参考下面两份文 档： 《ARM ArchitectureReference Manual ARMv7-A and ARMv7-R edition.pdf》 第 1469 页“B3.17 Oranization of the CP15 registers in a VMSA implementation”。《Cortex-A7 Technical ReferenceManua.pdf》 第55 页“Capter 4 System Control”。</p><p>CP15 协处理器一般用于存储系统管理， 但是在中断中也会使用到， CP15 协处理器一共有 16 个 32 位寄存器。 CP15 协处理器的访问通过如下两个指令完成：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MRC ;将 CP15 协处理器中的寄存器数据读到 ARM 寄存器中。</span></span>
<span class="line"><span>MCR ;将 ARM 寄存器的数据写入到 CP15 协处理器寄存器中。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>MRC 就是读 CP15 寄存器， MCR 就是写 CP15 寄存器， MCR 指令格式如下 :</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MCR{cond} p15, &lt;opc1&gt;, &lt;Rt&gt;, &lt;CRn&gt;, &lt;CRm&gt;, &lt;opc2&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><p>cond：指令执行的条件码，如果忽略的话就表示无条件执行。</p></li><li><p>opc1：协处理器要执行的操作码。</p></li><li><p>Rt： ARM 源寄存器，要写入到 CP15 寄存器的数据就保存在此寄存器中。</p></li><li><p>CRn： CP15 协处理器的目标寄存器。</p></li><li><p>CRm： 协处理器中附加的目标寄存器或者源操作数寄存器，如果不需要附加信息就将CRm 设置为 C0，否则结果不可预测。</p></li><li><p>opc2： 可选的协处理器特定操作码，当不需要的时候要设置为 0。</p></li></ul><p>MRC 的指令格式和 MCR 一样，只不过在 MRC 指令中 Rt 就是目标寄存器，也就是从CP15 指定寄存器读出来的数据会保存在 Rt 中。而 CRn 就是源寄存器，也就是要读取的写处理器寄存器。 假如我们要将 CP15 中 C0 寄存器的值读取到 R0 寄存器中，那么就可以使用如下命令：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MRC p15, 0, r0, c0, c0, 0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_2-相关寄存器" tabindex="-1">2. 相关寄存器 <a class="header-anchor" href="#_2-相关寄存器" aria-label="Permalink to &quot;2. 相关寄存器&quot;">​</a></h3><p>CP15 协处理器有 16 个 32 位寄存器， c0~c15，我们来看一下 c0、 c1、 c12 和 c15 这四个寄存器，因为我们目前学习的实验要用到这四个寄存器，其他的寄存器可以参考上面的两个文档即可。 通过 c0 寄存器可以获取到处理器内核信息；通过 c1 寄存器可以使能或禁止 MMU、 I/D Cache 等；通过 c12 寄存器可以设置中断向量偏移；通过 c15 寄存器可以获取 GIC 基地址。</p><h4 id="_2-1-c0-寄存器" tabindex="-1">2.1 c0 寄存器 <a class="header-anchor" href="#_2-1-c0-寄存器" aria-label="Permalink to &quot;2.1 c0 寄存器&quot;">​</a></h4><p>CP15 协处理器有 16 个 32 位寄存器， c0~c15，在使用 MRC 或者 MCR 指令访问这 16 个寄存器的时候，指令中的 CRn、 opc1、 CRm 和 opc2 通过不同的搭配，其得到的寄存器含义是不同的。比如 c0 在不同的搭配情况下含义如图 （参考 ARM ArchitectureReference Manual ARMv7-A and ARMv7-R edition 的 B3.17.1 CP15 register summary by coprocessor register number）</p><p><img src="`+u+'" alt="image-20260115183816999"></p><p>当 MRC/MCR 指令中的 CRn=c0， opc1=0， CRm=c0， opc2=0 的时候就表示此时的 c0 就是 MIDR 寄存器，也就是主 ID 寄存器，这个也是 c0 的基本作用。</p><p><img src="'+m+'" alt="image-20260115184055687"></p><p>对于 Cortex-A7内核来说， c0 作为 MDIR 寄存器的时候其含义如图（参考 ARM ArchitectureReference Manual ARMv7-A and ARMv7-R edition 的 B4.1.105 MIDR, Main ID Register, VMSA）</p><p><img src="'+g+'" alt="image-20260115184135205"></p><blockquote><p>bit [31:24]：厂商编号， 0X41， ARM。</p><p>bit [23:20]：内核架构的主版本号， ARM 内核版本一般使用 rnpn 来表示，比如 r0p1，其中 r0后面的 0 就是内核架构主版本号。</p><p>bit [19:16]：架构代码， 0XF， ARMv7 架构。</p><p>bit [15:4]：内核版本号， 0XC07， Cortex-A7 MPCore 内核。</p><p>bit [3:0]：内核架构的次版本号， rnpn 中的 pn，比如 r0p1 中 p1 后面的 1 就是次版本号。</p></blockquote><h4 id="_2-2-c1-寄存器" tabindex="-1">2.2 c1 寄存器 <a class="header-anchor" href="#_2-2-c1-寄存器" aria-label="Permalink to &quot;2.2 c1 寄存器&quot;">​</a></h4><p>c1 寄存器同样通过不同的配置，其代表的含义也不同，如图 ：</p><p><img src="'+R+'" alt="image-20260115184242910"></p><p>当 MRC/MCR 指令中的 CRn=c1， opc1=0， CRm=c0， opc2=0 的时候就表示此时的 c1 就是 <strong>SCTLR 寄存器，也就是系统控制寄存器</strong>，这个是 c1 的基本作用。</p><p><img src="'+b+'" alt="image-20260115184325917"></p><p>SCTLR 寄存器主要是完成控制功能的，比如使能或者禁止 MMU、 I/D Cache 等， c1 作为 SCTLR 寄存器的时候其含义如图（参考 ARM ArchitectureReference Manual ARMv7-A and ARMv7-R edition 的 B4.1.130 SCTLR, System Control Register, VMSA ）：</p><p><img src="'+A+`" alt="image-20260115184500316"></p><p>SCTLR 的位比较多，我们就只看本章会用到的几个位：</p><blockquote><p>bit [13]： V , 中断向量表基地址选择位，为 0 的话中断向量表基地址为 0X00000000，软件可以使用 VBAR 来重映射此基地址，也就是中断向量表重定位。为 1 的话中断向量表基地址为0XFFFF0000，此基地址不能被重映射。</p><p>bit [12]： I， I Cache 使能位，为 0 的话关闭 I Cache，为 1 的话使能 I Cache。</p><p>bit [11]： Z，分支预测使能位，如果开启 MMU 的话，此位也会使能。</p><p>bit [10]： SW， SWP 和 SWPB 使能位，当为 0 的话关闭 SWP 和 SWPB 指令，当为 1 的时候就使能 SWP 和 SWPB 指令。</p><p>bit [9:3]：未使用，保留。</p><p>bit [2]： C， D Cache 和缓存一致性使能位，为 0 的时候禁止 D Cache 和缓存一致性，为 1 时使能。</p><p>bit [1]： A，内存对齐检查使能位，为 0 的时候关闭内存对齐检查，为 1 的时候使能内存对齐检查。</p><p>bit [0]： M， MMU 使能位，为 0 的时候禁止 MMU，为 1 的时候使能 MMU。</p></blockquote><p>如果要读写 SCTLR 的话，就可以使用如下命令：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MRC p15, 0, &lt;Rt&gt;, c1, c0, 0 ;读取 SCTLR 寄存器，数据保存到 Rt 中。</span></span>
<span class="line"><span>MCR p15, 0, &lt;Rt&gt;, c1, c0, 0 ;将 Rt 中的数据写到 SCTLR(c1)寄存器中。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h4 id="_2-3-c12-寄存器" tabindex="-1">2.3 c12 寄存器 <a class="header-anchor" href="#_2-3-c12-寄存器" aria-label="Permalink to &quot;2.3 c12 寄存器&quot;">​</a></h4><p>c12 寄存器通过不同的配置，其代表的含义也不同，如图 （参考 ARM ArchitectureReference Manual ARMv7-A and ARMv7-R edition 的 VMSA CP15 c12 register summary, Security Extensions registers）</p><p><img src="`+P+`" alt="image-20260115184609692"></p><p>当 MRC/MCR 指令中的 CRn=c12， opc1=0， CRm=c0， opc2=0 的时候就表示此时 c12 为 <strong>VBAR 寄存器，也就是向量表基地址寄存器</strong>。设置中断向量表偏移的时候就需要将新的中断向量表基地址写入 VBAR 中，通过 VBAR 寄存器，可以设置异常向量表的映射地址。如果不把异常向量表 的映射地址告诉 CPU，在发生异常时， CPU 就找不到异常向量表，就无法处理异常 。比如在前面的例程中，代码链接的起始地址为0X87800000，而中断向量表肯定要放到最前面，也就是 0X87800000 这个地址处。所以就需要设置 VBAR 为 0X87800000，设置命令如下：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ldr r0, =0X87800000 ; r0=0X87800000</span></span>
<span class="line"><span>MCR p15, 0, r0, c12, c0, 0 ;将 r0 里面的数据写入到 c12 中，即 c12=0X87800000</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h4 id="_2-4-c15-寄存器" tabindex="-1">2.4 c15 寄存器 <a class="header-anchor" href="#_2-4-c15-寄存器" aria-label="Permalink to &quot;2.4 c15 寄存器&quot;">​</a></h4><p>c15 寄存器也可以通过不同的配置得到不同的含义，参考文档《Cortex-A7 Technical ReferenceManua.pdf》 第 68 页“4.2.16 c15 registers”，其配置如图 ：</p><p><img src="`+D+`" alt="image-20260115184740518"></p><p>我们需要 c15 作为 CBAR 寄存器，因为 GIC 的基地址就保存在 CBAR中，我们可以通过如下命令获取到 GIC 基地址：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MRC p15, 4, r1, c15, c0, 0 ; 获取 GIC 基础地址，基地址保存在 r1 中。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>获取到 GIC 基地址以后就可以设置 GIC 相关寄存器了，比如我们可以读取当前中断 ID，当前中断 ID 保存在 GICC_IAR 中，寄存器 GICC_IAR 属于 CPU 接口端寄存器，寄存器地址相对于 CPU 接口端起始地址的偏移为 0XC，因此获取当前中断 ID 的代码如下：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MRC p15, 4, r1, c15, c0, 0 ;获取 GIC 基地址</span></span>
<span class="line"><span>ADD r1, r1, #0X2000 ;GIC 基地址加 0X2000 得到 CPU 接口端寄存器起始地址</span></span>
<span class="line"><span>LDR r0, [r1, #0XC]  ;读取 CPU 接口端起始地址+0XC 处的寄存器值，也就是寄存器</span></span>
<span class="line"><span>                    ;GIC_IAR 的值</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="三、中断使能" tabindex="-1">三、中断使能 <a class="header-anchor" href="#三、中断使能" aria-label="Permalink to &quot;三、中断使能&quot;">​</a></h2><p>中断使能包括两部分，一个是 IRQ 或者 FIQ 总中断使能，另一个就是 ID0~ID1019 这 1020个中断源的使能。</p><h3 id="_1-irq-和-fiq-总中断使能" tabindex="-1">1. IRQ 和 FIQ 总中断使能 <a class="header-anchor" href="#_1-irq-和-fiq-总中断使能" aria-label="Permalink to &quot;1. IRQ 和 FIQ 总中断使能&quot;">​</a></h3><p>IRQ 和 FIQ 分别是外部中断和快速中断的总开关，要想使用 I.MX6U 上的外设中断就必须先打开 IRQ 中断。我们知道寄存器 CPSR 的 I=1 禁止 IRQ，当 I=0 使能 IRQ； F=1 禁止 FIQ， F=0 使能 FIQ。我们还有更简单的指令来完成 IRQ 或者 FIQ 的使能和禁止：</p><img src="`+M+'" alt="image-20230910111752761" style="zoom:50%;"><h3 id="_2-id0-id1019-中断使能和禁止" tabindex="-1">2. ID0 - ID1019 中断使能和禁止 <a class="header-anchor" href="#_2-id0-id1019-中断使能和禁止" aria-label="Permalink to &quot;2. ID0 - ID1019 中断使能和禁止&quot;">​</a></h3><p>GIC 寄存器 GICD_ISENABLERn 和 GICD_ ICENABLERn 用来完成外部中断的使能和禁止，对于 Cortex-A7 内核来说中断 ID 只使用了 512 个。一个 bit 控制一个中断 ID 的使能，那么就需要 512/32=16 个 GICD_ISENABLER 寄存器来完成中断的使能。同理，也需要 16 个GICD_ICENABLER 寄存器来完成中断的禁止。其中 GICD_ISENABLER0 的 bit[15:0]对应ID15~0 的 SGI 中断， GICD_ISENABLER0 的 bit[31:16]对应 ID31~16 的 PPI 中断。剩下的 GICD_ISENABLER1~GICD_ISENABLER15 就是控制 SPI 中断的。</p><h2 id="四、中断优先级设置" tabindex="-1">四、中断优先级设置 <a class="header-anchor" href="#四、中断优先级设置" aria-label="Permalink to &quot;四、中断优先级设置&quot;">​</a></h2><h3 id="_1-优先级数配置" tabindex="-1">1. 优先级数配置 <a class="header-anchor" href="#_1-优先级数配置" aria-label="Permalink to &quot;1. 优先级数配置&quot;">​</a></h3><p>Cortex-A7 的中断优先级可以分为抢占优先级和子优先级，两者同样是可以配置的。 GIC 控制器最多可以支持 256 个优先级，数字越小，优先级越高！ Cortex-A7 选择了 32 个优先级。在使用中断的时候需要初始化 GICC_PMR 寄存器，此寄存器用来决定使用几级优先级，寄存器结构如图：</p><img src="'+q+'" alt="image-20230910111946129" style="zoom:50%;"><p>GICC_PMR 寄存器只有低 8 位有效，这 8 位最多可以设置 256 个优先级，其他优先级数设置如表：</p><img src="'+v+'" alt="image-20230910112124153" style="zoom:50%;"><p>I.MX6U 是 Cortex-A7 内核，所以支持 32 个优先级， 因此 GICC_PMR 要设置为 0b11111000。</p><h3 id="_2-抢占优先级和子优先级位数设置" tabindex="-1">2. 抢占优先级和子优先级位数设置 <a class="header-anchor" href="#_2-抢占优先级和子优先级位数设置" aria-label="Permalink to &quot;2. 抢占优先级和子优先级位数设置&quot;">​</a></h3><p>抢占优先级和子优先级各占多少位是由寄存器 GICC_BPR 来决定的， GICC_BPR 寄存器结构如图</p><img src="'+U+'" alt="image-20230910112207791" style="zoom:50%;"><p>寄存器 GICC_BPR 只有低 3 位有效，其值不同，抢占优先级和子优先级占用的位数也不同，配置如表：</p><img src="'+G+'" alt="image-20230910112331142" style="zoom:50%;"><p>为了简单起见，一般将所有的中断优先级位都配置为抢占优先级，比如 I.MX6U 的优先级位数为 5(32 个优先级)，所以可以设置 Binary point 为 2，表示 5 个优先级位全部为抢占优先级。</p><h3 id="_3-优先级设置" tabindex="-1">3. 优先级设置 <a class="header-anchor" href="#_3-优先级设置" aria-label="Permalink to &quot;3. 优先级设置&quot;">​</a></h3><p>前面已经设置好了 I.MX6U 一共有 32 个抢占优先级，数字越小优先级越高。具体要使用某个中断的时候就可以设置其优先级为 0~31。某个中断 ID 的中断优先级设置由寄存器D_IPRIORITYR 来完成，前面说了 Cortex-A7 使用了 512 个中断 ID，每个中断 ID 配有一个优先级寄存器，所以一共有 512 个 D_IPRIORITYR 寄存器。如果优先级个数为 32 的话，使用寄存器 D_IPRIORITYR 的 bit[7:4] 来设置优先级，也就是说实际的优先级要左移 3 位。比如要设置ID40 中断的优先级为 5，示例代码如下：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">GICD_IPRIORITYR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>',136)])])}const y=a(x,[["render",k]]);export{E as __pageData,y as default};
